#!/bin/bash
set -euo pipefail
test "$(id -un)" = pwa209
case "$(hostname -f)" in *.narval.calcul.quebec) ;; *) exit 2 ;; esac
module load StdEnv/2023 python/3.11.5 cuda/12.6 arrow/19.0.1
source /home/pwa209/hhw-environment/bin/activate
export PYTHONPATH=/scratch/pwa209/horsehair-worm/releases/20261021-6ed201653dfa-4f3903d7c26e/src:"${PYTHONPATH:-}"
export PYTHONDONTWRITEBYTECODE=1 TZ=UTC
python -s -B -u - <<'PY'
from pathlib import Path
import os,json,hashlib,base64,subprocess,shlex,importlib.util,re
assert os.geteuid()==3164768
r=Path('/scratch/pwa209/horsehair-worm');s=r/'maintenance/terminal-controller-diagnostic-support-v2-20261103';s.mkdir()
payload={'compact-terminal-controller-reads-20261103.py': '', 'test_compact_terminal_controller_reads_20261103.py': '', 'reconcile-stopped-worker-archives-20261103.py': ''}
pins={'compact-terminal-controller-reads-20261103.py': '3e99bc89133cd06f4f3c120afd4653ba60fe9743530f0da8fda3df57e451ca60', 'test_compact_terminal_controller_reads_20261103.py': '0ebcd461f1297674371777cd0c6ffd6ac5dbe4758ac723292ed682b57d9e6176', 'reconcile-stopped-worker-archives-20261103.py': 'd0d19a8c5e9fc1317b05c24034a95bb1132d6ef4389e3992fb9fe936e1a7e062'}
for n,v in payload.items():
 p=s/n;p.write_bytes(base64.b64decode(v));assert hashlib.sha256(p.read_bytes()).hexdigest()==pins[n]
(s/'source-manifest.json').write_text(json.dumps(pins,indent=2))
spec=importlib.util.spec_from_file_location('controller_diagnostic_compaction',s/'compact-terminal-controller-reads-20261103.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
campaign=r/'maintenance/study-af-campaign-v1-20261021/agent-final-f64-v1'
sources=[r/'maintenance/study-primary-external-census-policy-v1-20261023/native-7046213']+sorted(campaign.glob('controller-[0-3]-*'))
items=[];skipped=[]
for p in sources:
 match=re.fullmatch(r'(?:controller-[0-3]-|native-)([1-9][0-9]*)',p.name)
 if not match:continue
 job=match[1]
 try:
  registration=m.source_registration(p,job,root=r)
 except (ValueError,KeyError,StopIteration,FileNotFoundError) as e:
  skipped.append({'path':str(p),'reason':str(e)[:300]});continue
 items.append({'path':str(p),'job':job,'binding_documents':[],'protected_paths':[]})
assert items and items[0]['job']=='7046213'
request={'case':str(r/'maintenance/terminal-controller-diagnostic-compaction-v2-20261103'),'target_free_files':300000,'minimum_files_removed':60000,'sources':items,'binding_documents':[{'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in [campaign/'state.json.gz',campaign/'campaign-plan.json',campaign/'state-binding.json']],'protected_paths':[]}
raw=(json.dumps(request,indent=2,sort_keys=True)+'\n').encode();(s/'request.json').write_bytes(raw);qsha=hashlib.sha256(raw).hexdigest()
(s/'preflight.json').write_text(json.dumps({'eligible_sources':len(items),'skipped':skipped},indent=2))
script=s/'controller-compact.sbatch'
text='#!/bin/bash\n#SBATCH --account=def-ptewarie_cpu\n#SBATCH --job-name=hhw-terminal-controller-read-compaction-20261103\n#SBATCH --cpus-per-task=1\n#SBATCH --mem=16G\n#SBATCH --time=04:00:00\n#SBATCH --hold\n#SBATCH --output=/scratch/pwa209/horsehair-worm/maintenance/terminal-controller-diagnostic-support-v2-20261103/native.log\nset -euo pipefail\ntest "$(id -un)" = pwa209\nmodule load StdEnv/2023 python/3.11.5 cuda/12.6 arrow/19.0.1\nsource /home/pwa209/hhw-environment/bin/activate\nexport PYTHONPATH=/scratch/pwa209/horsehair-worm/releases/20261021-6ed201653dfa-4f3903d7c26e/src:"${PYTHONPATH:-}"\nexport PYTHONDONTWRITEBYTECODE=1 TZ=UTC OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1\ncd /scratch/pwa209/horsehair-worm/maintenance/terminal-controller-diagnostic-support-v2-20261103\npython -s -B -m pytest test_compact_terminal_controller_reads_20261103.py -q -p no:cacheprovider --basetemp "$SLURM_TMPDIR/controller-diagnostic-tests" --junitxml tests.xml\npython -s -B - <<\'CHECK\'\nimport xml.etree.ElementTree as E\nt=list(E.parse(\'tests.xml\').getroot().iter(\'testcase\'))\nassert len(t)==50 and not any(list(c.iter(k)) for c in t for k in [\'failure\',\'error\',\'skipped\'])\nCHECK\npython -s -B reconcile-stopped-worker-archives-20261103.py\npython -s -B compact-terminal-controller-reads-20261103.py --request /scratch/pwa209/horsehair-worm/maintenance/terminal-controller-diagnostic-support-v2-20261103/request.json --request-sha256 REQUEST_SHA --wrapper-sha256 WRAPPER_SHA\n'
text=text.replace('WRAPPER_SHA',pins['compact-terminal-controller-reads-20261103.py']).replace('REQUEST_SHA',qsha);script.write_text(text)
cmd=['sbatch','--parsable','--dependency=afterany:8403868',str(script)];(s/'submit-intent.json').write_text(json.dumps(cmd))
p=subprocess.run(cmd,capture_output=True,text=True,timeout=90);(s/'submit-response.json').write_text(json.dumps({'code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}));p.check_returncode();job=p.stdout.strip().split(';')[0];assert job.isdigit()
def observe():
 p=subprocess.run(['scontrol','show','job',job,'-o'],capture_output=True,text=True,timeout=90);p.check_returncode();assert not p.stderr
 f=dict(x.split('=',1) for x in shlex.split(p.stdout) if '=' in x);assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['Command']==str(script) and f['JobName']=='hhw-terminal-controller-read-compaction-20261103';return f
f=observe();assert f['JobState']=='PENDING' and f['Reason']=='JobHeldUser' and f['NumCPUs']=='1' and f['MinMemoryNode'] in ['16G','16384M'] and f['TimeLimit']=='04:00:00';(s/'held.json').write_text(json.dumps(f))
(s/'release-intent.json').write_text(json.dumps(['scontrol','release',job]));p=subprocess.run(['scontrol','release',job],capture_output=True,text=True,timeout=90);(s/'release-response.json').write_text(json.dumps({'code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}))
f=observe();assert f['JobState']=='RUNNING' or f['JobState']=='PENDING' and f['Reason'] not in ['JobHeldUser','JobHeldAdmin'] and int(f['Priority'])>0
result={'job_id':job,'request_sha256':qsha,'sources':len(items),'skipped':skipped,'actual_unheld':f};(s/'registration.json').write_text(json.dumps(result,indent=2));print('CONTROLLER_DIAGNOSTIC_REGISTRATION '+json.dumps(result),flush=True)
PY
